/* ============ TEMPLE DUEL — base ============ */
:root{
  --ink:#06050b;
  --ink-2:#0b0914;
  --paper:#efe6d2;
  --paper-dim:rgba(239,230,210,.58);
  --gold:#d9b45f;
  --gold-bright:#f8e3a4;
  --gold-deep:#8a6a2f;
  --red:#b3372f;
  --teal:#7fe3cf;
  --blue:#8fd8ff;
  --violet:#b07cff;
  --font-display:"Cinzel","Iowan Old Style","Palatino Linotype","Times New Roman",serif;
  --font-jp:"Shippori Mincho B1","Yu Mincho","Hiragino Mincho ProN","Noto Serif JP",serif;
  --board-w:min(92vw, 620px, 68vh);
  --ease-out:cubic-bezier(.16,1,.3,1);
}
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  min-height:100%;
  background:var(--ink);
  color:var(--paper);
  font-family:var(--font-display);
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}
button{font:inherit;color:inherit}
button:focus-visible,.card:focus-visible{outline:2px solid var(--gold-bright);outline-offset:3px}
::selection{background:rgba(217,180,95,.3)}

/* ============ background scene ============ */
.scene{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none;background:#05040a}
.sky{
  position:absolute;inset:0;
  background:
    radial-gradient(120% 85% at 50% -10%, #232046 0%, #121026 38%, #08070f 70%, #040309 100%),
    linear-gradient(180deg,#0a0916,#05040a);
}
.sky::after{
  content:"";position:absolute;inset:0;
  background:radial-gradient(55% 45% at 50% 62%, rgba(217,180,95,.07), transparent 70%);
}
.moon{
  position:absolute;top:5vh;right:7vw;width:clamp(110px,16vw,240px);aspect-ratio:1;border-radius:50%;
  background:radial-gradient(circle at 38% 33%, #fff8e3 0%, #f2e2b8 45%, #cbb078 78%, #9c7d48 100%);
  box-shadow:0 0 50px rgba(248,227,164,.28),0 0 140px rgba(248,227,164,.16),inset -14px -18px 34px rgba(90,64,24,.35);
  opacity:.82;
}
.moon .crater{position:absolute;border-radius:50%;background:rgba(120,94,48,.16);box-shadow:inset 2px 2px 4px rgba(255,255,255,.16)}
.moon .c1{width:22%;height:22%;left:24%;top:30%}
.moon .c2{width:13%;height:13%;left:58%;top:22%}
.moon .c3{width:17%;height:17%;left:52%;top:58%}
.stars{position:absolute;inset:0}
.stars i{position:absolute;width:2px;height:2px;border-radius:50%;background:#f8ecc9;box-shadow:0 0 6px rgba(248,236,201,.8);animation:twinkle var(--tw,4s) ease-in-out infinite;animation-delay:var(--td,0s)}
.mountains{position:absolute;left:0;right:0;bottom:0;width:100%;height:62vh;opacity:.95}
.torii{
  position:absolute;left:50%;bottom:-8vh;transform:translateX(-50%);
  width:min(1200px,120vw);height:80vh;opacity:.55;
  filter:drop-shadow(0 0 34px rgba(179,55,47,.2)) drop-shadow(0 0 90px rgba(217,180,95,.06));
}
.enso{
  position:absolute;left:50%;top:47%;transform:translate(-50%,-50%);
  width:min(760px,92vw);aspect-ratio:1;border-radius:50%;
  border:2px solid rgba(217,180,95,.07);
  box-shadow:inset 0 0 80px rgba(217,180,95,.04),0 0 120px rgba(217,180,95,.03);
}
.enso::after{
  content:"";position:absolute;inset:7%;border-radius:50%;
  border:1px dashed rgba(217,180,95,.05);
}
.fog{position:absolute;left:-20%;width:140%;height:36vh;pointer-events:none;filter:blur(42px);opacity:.5}
.fog-a{bottom:-8vh;background:radial-gradient(60% 100% at 30% 50%,rgba(96,124,168,.22),transparent 70%);animation:fogDrift 28s ease-in-out infinite alternate}
.fog-b{bottom:8vh;background:radial-gradient(55% 100% at 70% 50%,rgba(150,120,200,.14),transparent 70%);animation:fogDrift 36s ease-in-out infinite alternate-reverse}
.lanterns{position:absolute;inset:0}
.lantern{
  position:absolute;width:var(--s,7px);height:var(--s,7px);border-radius:50%;
  background:radial-gradient(circle,#ffe6a8,#f3a94f 55%,rgba(243,169,79,0) 72%);
  box-shadow:0 0 14px rgba(255,196,110,.55),0 0 38px rgba(255,160,60,.25);
  animation:lanternFloat var(--dur,18s) linear infinite;animation-delay:var(--delay,0s);opacity:0;
}
#fx{position:fixed;inset:0;z-index:5;pointer-events:none}

/* ============ layout ============ */
.game{
  position:relative;z-index:10;
  width:min(100%, 1040px);
  margin:0 auto;
  padding:max(10px, env(safe-area-inset-top)) 18px max(14px, env(safe-area-inset-bottom));
  display:flex;flex-direction:column;align-items:center;gap:8px;
  min-height:100svh;
}
.topbar{
  width:100%;display:flex;align-items:center;justify-content:space-between;gap:14px;
  padding:6px 2px 4px;
}
.brand{display:flex;align-items:center;gap:12px;min-width:0}
.brand-seal{
  flex:0 0 auto;width:44px;height:44px;display:grid;place-items:center;
  font-family:var(--font-jp);font-size:24px;color:var(--gold-bright);
  border:1px solid rgba(217,180,95,.5);border-radius:4px;
  background:radial-gradient(circle at 50% 30%,rgba(217,180,95,.2),rgba(10,8,18,.9));
  box-shadow:inset 0 0 20px rgba(217,180,95,.14),0 0 24px rgba(0,0,0,.6);
  text-shadow:0 0 12px rgba(248,227,164,.5);
}
.brand-text{min-width:0}
.brand h1{
  margin:0;font-family:var(--font-display);font-weight:600;
  font-size:clamp(14px,1.7vw,21px);letter-spacing:.24em;color:var(--gold-bright);
  white-space:nowrap;text-shadow:0 0 22px rgba(248,227,164,.25);
}
.brand p{
  margin:2px 0 0;font-family:var(--font-jp);font-size:9px;letter-spacing:.26em;
  color:rgba(239,230,210,.42);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.turn-pill{
  display:flex;align-items:center;gap:9px;padding:8px 15px;border-radius:999px;
  border:1px solid rgba(217,180,95,.28);background:rgba(8,7,16,.66);
  font-size:9px;letter-spacing:.2em;color:var(--gold);white-space:nowrap;
  backdrop-filter:blur(8px);transition:color .3s,border-color .3s,box-shadow .3s;
}
.turn-pill .dot{width:6px;height:6px;border-radius:50%;background:var(--gold-bright);box-shadow:0 0 10px var(--gold-bright);animation:dotPulse 1.8s ease-in-out infinite}
.turn-pill.enemy{color:#ff9d8d;border-color:rgba(255,110,90,.35);box-shadow:0 0 22px rgba(255,80,60,.1)}
.turn-pill.enemy .dot{background:#ff6b5a;box-shadow:0 0 10px #ff6b5a}
.turn-pill.over{color:var(--paper-dim);border-color:rgba(239,230,210,.15)}
.turn-pill.over .dot{background:var(--paper-dim);box-shadow:none;animation:none}
.top-actions{display:flex;align-items:center;gap:8px}
.icon-btn{
  width:36px;height:36px;display:grid;place-items:center;border-radius:50%;
  border:1px solid rgba(217,180,95,.24);background:rgba(8,7,16,.6);color:var(--gold);
  cursor:pointer;transition:transform .2s var(--ease-out),border-color .2s,color .2s,background .2s;
}
.icon-btn svg{width:17px;height:17px}
.icon-btn:hover{transform:translateY(-2px);border-color:rgba(248,227,164,.55);color:var(--gold-bright);background:rgba(30,24,46,.8)}
.icon-btn .sound-x{display:none}
.icon-btn.muted .sound-wave{display:none}
.icon-btn.muted .sound-x{display:block}
.btn{
  border:1px solid rgba(217,180,95,.4);border-radius:4px;background:rgba(14,11,24,.72);
  color:var(--gold-bright);font-family:var(--font-display);font-size:10px;letter-spacing:.16em;
  padding:9px 16px;cursor:pointer;transition:transform .18s var(--ease-out),background .2s,border-color .2s,box-shadow .2s;
}
.btn:hover{transform:translateY(-1px);border-color:rgba(248,227,164,.8);box-shadow:0 0 20px rgba(217,180,95,.15)}
.btn:active{transform:translateY(0) scale(.98)}
.btn:disabled{opacity:.35;cursor:not-allowed;transform:none;box-shadow:none}
.btn.small{padding:7px 12px;font-size:9px}
.btn.ghost{background:rgba(8,7,16,.45)}
.btn.primary{
  background:linear-gradient(180deg,rgba(217,180,95,.95),rgba(160,118,44,.95));
  border-color:rgba(248,227,164,.9);color:#1a1106;font-weight:700;
  box-shadow:0 0 28px rgba(217,180,95,.28),inset 0 1px 0 rgba(255,255,255,.4);
}
.btn.primary:hover{box-shadow:0 0 40px rgba(248,227,164,.45),inset 0 1px 0 rgba(255,255,255,.5)}
.btn.danger{border-color:rgba(255,110,90,.5);color:#ffb3a6;background:rgba(60,14,14,.4)}
.btn.danger:hover{border-color:#ff8d7d;box-shadow:0 0 24px rgba(255,80,60,.2)}

