cat >> styles.css <<'EOF'

/* ============ duelist panels ============ */
.duelist{
  width:min(100%, 760px);display:flex;align-items:center;gap:12px;
  padding:8px 14px;border-radius:6px;position:relative;
  border:1px solid rgba(217,180,95,.16);
  background:linear-gradient(90deg,rgba(18,15,30,.86),rgba(9,8,16,.7) 55%,rgba(18,15,30,.86));
  box-shadow:inset 0 0 30px rgba(0,0,0,.5),0 8px 30px rgba(0,0,0,.25);
  transition:border-color .4s,box-shadow .4s;
}
.duelist::before{
  content:"";position:absolute;inset:3px;border:1px solid rgba(217,180,95,.06);border-radius:3px;pointer-events:none;
}
.duelist.active{border-color:rgba(248,227,164,.42);box-shadow:inset 0 0 30px rgba(217,180,95,.06),0 0 30px rgba(217,180,95,.08)}
.duelist.enemy.active{border-color:rgba(255,110,90,.38);box-shadow:inset 0 0 30px rgba(255,80,60,.05),0 0 30px rgba(255,80,60,.08)}
.portrait{
  flex:0 0 auto;width:42px;height:42px;border-radius:50%;display:grid;place-items:center;position:relative;
  font-family:var(--font-jp);font-size:19px;color:var(--paper);
  border:1px solid rgba(217,180,95,.35);
  background:radial-gradient(circle at 50% 35%,rgba(217,180,95,.16),rgba(5,4,10,.95));
}
.portrait i{position:absolute;inset:-4px;border-radius:50%;border:1px solid rgba(217,180,95,.18);border-top-color:rgba(248,227,164,.6);animation:spin 9s linear infinite}
.enemy-portrait{color:#ffb3a6;border-color:rgba(255,110,90,.32);background:radial-gradient(circle at 50% 35%,rgba(179,55,47,.22),rgba(5,4,10,.95))}
.enemy-portrait i{border-color:rgba(255,110,90,.14);border-top-color:rgba(255,140,120,.65)}
.duelist-main{flex:1;min-width:0}
.duelist-name{display:flex;align-items:baseline;gap:9px;line-height:1}
.duelist-name .jp{font-family:var(--font-jp);font-size:13px;letter-spacing:.12em;color:var(--paper)}
.duelist-name .en{font-size:8px;letter-spacing:.2em;color:rgba(239,230,210,.38)}
.lp-line{display:flex;align-items:center;gap:8px;margin-top:6px}
.lp-tag{font-size:7px;letter-spacing:.16em;color:rgba(239,230,210,.42)}
.lp-number{
  font-family:var(--font-display);font-weight:700;font-size:19px;line-height:1;
  color:var(--gold-bright);min-width:52px;letter-spacing:.04em;
  text-shadow:0 0 14px rgba(248,227,164,.3);font-variant-numeric:tabular-nums;
  transition:color .25s;
}
.player .lp-number{color:#bff4e8;text-shadow:0 0 14px rgba(127,227,207,.28)}
.lp-number.hurt{color:#ff9d8d;text-shadow:0 0 18px rgba(255,80,60,.5)}
.lp-track{
  flex:1;height:7px;border-radius:99px;position:relative;overflow:hidden;
  background:rgba(255,255,255,.06);border:1px solid rgba(217,180,95,.18);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.7);
}
.lp-fill{
  position:absolute;inset:0;width:100%;transform-origin:left center;
  background:linear-gradient(90deg,#8d2b25,#e0604a 60%,#ffb36a);
  box-shadow:0 0 12px rgba(255,120,90,.45);
  transition:width .65s var(--ease-out);
}
.player .lp-fill{background:linear-gradient(90deg,#1f6b63,#4fc7b1 55%,#b6f7e8);box-shadow:0 0 12px rgba(127,227,207,.4)}
.lp-track::after{
  content:"";position:absolute;inset:0;
  background:repeating-linear-gradient(90deg,transparent 0 calc(25% - 1px),rgba(5,4,10,.6) calc(25% - 1px) 25%);
  pointer-events:none;
}
.shield-chip{
  font-size:8px;letter-spacing:.1em;color:#bfeaff;padding:3px 7px;border-radius:99px;
  border:1px solid rgba(143,216,255,.4);background:rgba(30,80,110,.35);
  box-shadow:0 0 14px rgba(143,216,255,.18);white-space:nowrap;animation:shieldGlow 2.4s ease-in-out infinite;
}
.duelist-side{flex:0 0 auto}
.side-tag{
  display:inline-block;font-size:7px;letter-spacing:.18em;color:rgba(239,230,210,.34);
  padding:4px 8px;border:1px solid rgba(239,230,210,.1);border-radius:2px;
}
.duelist.active .side-tag{color:var(--gold-bright);border-color:rgba(248,227,164,.35)}
.duelist.enemy.active .side-tag{color:#ffb3a6;border-color:rgba(255,140,120,.4)}
.duelist.hit{animation:panelHit .5s ease-out}
.duelist.direct-target{cursor:crosshair;border-color:rgba(255,110,90,.65);box-shadow:0 0 34px rgba(255,80,60,.2),inset 0 0 30px rgba(255,80,60,.06);animation:directPulse 1s ease-in-out infinite}

/* ============ log strip ============ */
.log-strip{
  width:min(100%, 760px);display:flex;align-items:center;gap:9px;min-height:24px;
  padding:2px 10px;font-family:var(--font-jp);font-size:10px;letter-spacing:.04em;
  color:rgba(239,230,210,.5);
}
.log-mark{
  flex:0 0 auto;width:16px;height:16px;display:grid;place-items:center;font-size:9px;
  color:var(--gold);border:1px solid rgba(217,180,95,.3);border-radius:50%;
}
.log-text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .2s}
.log-text.hot{color:#ffb3a6}
.log-text.good{color:#bff4e8}

/* ============ board ============ */
.board{
  width:var(--board-w);position:relative;
  padding:clamp(8px,1.5vw,14px);
  display:flex;flex-direction:column;gap:clamp(6px,1.1vw,10px);
  border-radius:10px;
  border:1px solid rgba(217,180,95,.2);
  background:
    radial-gradient(80% 60% at 50% 48%,rgba(34,26,54,.5),transparent 72%),
    linear-gradient(180deg,rgba(12,10,22,.82),rgba(6,5,12,.9));
  box-shadow:
    0 0 0 1px rgba(0,0,0,.7),
    inset 0 0 60px rgba(0,0,0,.65),
    0 30px 80px rgba(0,0,0,.55),
    0 0 60px rgba(217,180,95,.04);
  transition:border-color .5s,box-shadow .5s;
}
.board.enemy-turn{border-color:rgba(255,110,90,.22);box-shadow:0 0 0 1px rgba(0,0,0,.7),inset 0 0 60px rgba(80,10,10,.12),0 30px 80px rgba(0,0,0,.55)}
.board-halo{
  position:absolute;left:50%;top:50%;width:88%;aspect-ratio:1;transform:translate(-50%,-50%);
  border-radius:50%;pointer-events:none;
  background:radial-gradient(circle,rgba(217,180,95,.05),transparent 62%);
  filter:blur(6px);
}
.board-corners{position:absolute;inset:4px;pointer-events:none}
.board-corners i{position:absolute;width:16px;height:16px;border-color:rgba(217,180,95,.5);border-style:solid;border-width:0}
.board-corners i:nth-child(1){top:0;left:0;border-top-width:1px;border-left-width:1px}
.board-corners i:nth-child(2){top:0;right:0;border-top-width:1px;border-right-width:1px}
.board-corners i:nth-child(3){bottom:0;left:0;border-bottom-width:1px;border-left-width:1px}
.board-corners i:nth-child(4){bottom:0;right:0;border-bottom-width:1px;border-right-width:1px}
.row{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(5px,1.1vw,10px);position:relative;z-index:1}
.row-tiny{width:74%;margin-inline:auto;gap:clamp(4px,.8vw,8px)}
.divider{
  display:flex;align-items:center;gap:10px;padding:2px 4px;position:relative;z-index:1;
}
.divider-line{flex:1;height:1px;background:linear-gradient(90deg,transparent,rgba(217,180,95,.3),transparent)}
.divider-text{
  font-size:7px;letter-spacing:.22em;color:rgba(217,180,95,.7);white-space:nowrap;
  font-family:var(--font-display);
}
.divider-text.enemy{color:rgba(255,140,120,.8)}
EOF

cat >> styles.css <<'EOF'

/* ============ card slots ============ */
.slot{position:relative;aspect-ratio:1;border-radius:9px}
.slot::before{
  content:"";position:absolute;inset:0;border-radius:9px;
  border:1px solid rgba(217,180,95,.14);
  background:
    radial-gradient(circle at 50% 42%,rgba(217,180,95,.06),transparent 62%),
    linear-gradient(180deg,rgba(255,255,255,.02),rgba(0,0,0,.18));
  box-shadow:inset 0 0 22px rgba(0,0,0,.55);
  transition:border-color .3s,box-shadow .3s;
}
.slot::after{
  content:"◇";position:absolute;inset:0;display:grid;place-items:center;
  color:rgba(217,180,95,.1);font-size:clamp(10px,1.5vw,16px);
  opacity:0;transition:opacity .5s;pointer-events:none;
}
.slot.is-empty::before{border-style:dashed;border-color:rgba(217,180,95,.1);background:radial-gradient(circle,rgba(179,55,47,.05),transparent 65%)}
.slot.is-empty::after{opacity:1}
.slot.selected::before{border-color:rgba(248,227,164,.75);box-shadow:inset 0 0 26px rgba(217,180,95,.12),0 0 24px rgba(217,180,95,.18)}
.slot.selected::after{opacity:0}
.slot.targetable::before{border-color:rgba(255,110,90,.7);animation:targetPulse 1.05s ease-in-out infinite}

.card-motion{
  position:absolute;inset:0;
  animation:bob var(--bob-dur,6.5s) ease-in-out infinite;
  animation-delay:var(--bob-delay,0s);
  will-change:transform;
}
.card{
  position:absolute;inset:0;cursor:pointer;border-radius:9px;
  perspective:760px;
  -webkit-tap-highlight-color:transparent;
  --lift:0px;--scale:1;--rx:0deg;--ry:0deg;
}
.card-inner{
  position:relative;width:100%;height:100%;transform-style:preserve-3d;
  transform:perspective(760px) rotateX(var(--rx)) rotateY(var(--ry)) translateY(var(--lift)) scale(var(--scale));
  transition:transform .22s var(--ease-out),filter .25s;
}
@media (hover:hover){
  .card:hover{--lift:-4px;--scale:1.035;z-index:4}
  .card:hover .card-face{box-shadow:0 0 0 1px rgba(248,227,164,.55),0 10px 26px rgba(0,0,0,.6),0 0 26px rgba(217,180,95,.16),inset 0 0 18px rgba(0,0,0,.8)}
}
.card.selected{--lift:-3px;--scale:1.02;z-index:4}
.card.selected .card-face{
  box-shadow:0 0 0 2px var(--gold-bright),0 0 30px rgba(248,227,164,.4),0 12px 30px rgba(0,0,0,.6),inset 0 0 18px rgba(0,0,0,.8);
}
.card.targetable{--lift:-3px;--scale:1.02;z-index:4;cursor:crosshair}
.card.targetable .card-face{
  box-shadow:0 0 0 2px #ff6b5a,0 0 30px rgba(255,90,70,.55),inset 0 0 20px rgba(255,60,40,.14);
  animation:targetFlash 1.05s ease-in-out infinite;
}
.card-face{
  position:absolute;inset:0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:8px;backface-visibility:hidden;
  background:linear-gradient(160deg,#17141f 0%,#0a0810 60%,#07060c 100%);
  border:1px solid color-mix(in srgb,var(--accent) 45%,#b08a44);
  box-shadow:
    0 0 0 1px rgba(0,0,0,.85),
    0 7px 18px rgba(0,0,0,.5),
    inset 0 0 18px rgba(0,0,0,.75);
  transition:box-shadow .25s;
}
.card-face::before{
  content:"";position:absolute;inset:0;border-radius:8px;pointer-events:none;z-index:3;
  background:
    linear-gradient(135deg,rgba(248,227,164,.5),transparent 14%) top left/18% 18% no-repeat,
    linear-gradient(-45deg,rgba(248,227,164,.5),transparent 14%) top right/18% 18% no-repeat,
    linear-gradient(45deg,rgba(248,227,164,.5),transparent 14%) bottom left/18% 18% no-repeat,
    linear-gradient(-135deg,rgba(248,227,164,.5),transparent 14%) bottom right/18% 18% no-repeat;
  opacity:.5;
}
.card-art{
  position:relative;flex:1 1 auto;min-height:0;margin:5% 5% 0;overflow:hidden;
  border-radius:3px;border:1px solid color-mix(in srgb,var(--accent) 30%,#000);
  background:#05050a;
}
.card-art svg{display:block;width:100%;height:100%}
.card-art::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:
    repeating-linear-gradient(0deg,rgba(255,255,255,.03) 0 1px,transparent 1px 3px),
    radial-gradient(circle at 50% 32%,transparent 38%,rgba(0,0,0,.52) 100%);
  mix-blend-mode:overlay;
}
.attr{
  position:absolute;top:5%;left:5%;z-index:2;width:17%;aspect-ratio:1;border-radius:50%;
  display:grid;place-items:center;font-family:var(--font-jp);font-size:clamp(5px,.72vw,9px);
  color:#0d0913;background:radial-gradient(circle at 38% 32%,#fff8df,var(--accent) 62%,#5b421f);
  border:1px solid rgba(255,255,255,.45);
