  }));

  for (let round = 0; round < 14; round++) {
    let s = await snap();
    if (s.overlay) break;
    // relics: activate each unused player relic once
    for (let r = 0; r < 4; r++) {
      const clicked = await page.evaluate((idx) => {
        const el = document.querySelectorAll('.row-tiny[data-side=player] .card')[idx];
        if (!el || el.classList.contains('spent')) return false;
        el.click(); return true;
