      const hasAct = await page.evaluate(() => !!document.querySelector('[data-action=activate]:not([disabled])'));
      if (hasAct) {
        await page.evaluate(() => document.querySelector('[data-action=activate]').click());
        await page.waitForTimeout(1000);
        // buff target
        const buffMode = await page.evaluate(() => document.querySelector('#cmd-text').textContent.includes('receive +800'));
        if (buffMode) {
          await page.evaluate(() => document.querySelector('.row-big[data-side=player] .card')?.click());
          await page.waitForTimeout(900);
        }
      }
    }
    // attacks
    for (let a = 0; a < 6; a++) {
      s = await snap();
      if (s.overlay) break;
      const selected = await page.evaluate(() => {
        const el = document.querySelector('.row-big[data-side=player] .card:not(.acted)');
        if (!el) return false;
        el.click(); return true;
      });
      if (!selected) break;
      await page.waitForTimeout(200);
      const hasAttack = await page.evaluate(() => !!document.querySelector('[data-action=attack]:not([disabled])'));
      if (!hasAttack) break;
      await page.evaluate(() => document.querySelector('[data-action=attack]').click());
      await page.waitForTimeout(250);
      await page.evaluate(() => {
        const target = document.querySelector('.row-big[data-side=enemy] .card');
        if (target) target.click();
        else document.querySelector('#enemy-panel').click();
      });
      await page.waitForTimeout(2400);
    }
    s = await snap();
    console.log(`round ${round}`, JSON.stringify(s));
    if (s.overlay) break;
    // end turn
    const endEnabled = await page.evaluate(() => !!document.querySelector('[data-action=end]:not([disabled])'));
    if (!endEnabled) { await page.waitForTimeout(1500); }
    await page.evaluate(() => document.querySelector('[data-action=end]')?.click());
    await page.waitForTimeout(9500);
    s = await snap();
    console.log(` after enemy`, JSON.stringify(s));
    if (s.overlay) break;
  }
  const final = await snap();
  console.log('FINAL', JSON.stringify(final));
  console.log('ERRORS', JSON.stringify(errors));
  await page.screenshot({ path: 'screenshots/playtest-final.png' });
  await browser.close();
})();
