          await cmd('activate'); await page.waitForTimeout(900);
        }
      }
      // burn finisher or when no enemy monsters
      s = await read();
      if (s.lpE <= 700 || s.eCards.length === 0) {
        await clickCard('player', 'tiny', 3);
        if (await page.evaluate(() => !!document.querySelector('[data-action=activate]:not([disabled])'))) {
          await cmd('activate'); await page.waitForTimeout(900);
        }
      }
      // buff if enables a kill
      s = await read();
      let buffUsed = false;
      for (const p of s.pCards) {
        if (p.acted) continue;
        const target = s.eCards.find(e => p.atk <= e.def && p.atk + 800 > e.def);
