      // attacks: choose best favorable target per monster
      for (let n = 0; n < 6; n++) {
        s = await read();
        if (s.overlay) break;
        if (!s.pCards.length) break;
        let best = null;
        for (const p of s.pCards) {
          if (p.acted) continue;
          for (const e of s.eCards) {
            const delta = p.atk - e.def;
            if (delta > 0 && (!best || delta > best.delta)) best = { p, e, delta };
          }
        }
        if (!best) break;
        await clickCard('player', 'big', best.p.i);
        if (!(await cmd('attack'))) break;
        await page.waitForTimeout(220);
        await clickCard('enemy', 'big', best.e.i);
        await page.waitForTimeout(2700);
      }
      s = await read();
      if (s.overlay) break;
      console.log(`game ${game} turn ${turn}: LP ${s.lpP}/${s.lpE} pCards ${s.pCards.length} eCards ${s.eCards.length}`);
      if (await cmd('end')) {
        for (let i = 0; i < 30; i++) {
          await page.waitForTimeout(500);
          s = await read();
          if (s.overlay || (s.turn.includes('YOUR MOVE') && !s.busy)) break;
        }
      }
      if (s.overlay) break;
    }
    s = await read();
    console.log(`GAME ${game} RESULT`, s.overlayTitle, 'LP', s.lpP, s.lpE, 'turns', s.turn);
    if (s.overlay && s.overlayTitle === 'VICTORY') {
      await page.waitForTimeout(1400);
      await page.screenshot({ path: 'screenshots/victory.png' });
    }
  }
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})();
